-- Die Startseite im Editor
--
-- Zweiter Schritt der Umstellung. Die Startseite ist der schwierigste Fall:
-- farbige Baender ueber die ganze Breite, ein Zeitstrahl mit Bildwechsel und
-- zwei Aktionskaesten. Nichts davon liess sich mit den bisherigen Bausteinen
-- nachbauen; vier neue kamen dafuer dazu.
--
-- Wieder unter eigener Adresse neben der Code-Fassung, damit sich beide
-- vergleichen lassen.

INSERT INTO public.site_pages (slug, title, content, draft_content, seo_description, is_published, published_at)
VALUES (
  'startseite-neu',
  'Startseite',
  '{"content": [{"type": "Willkommen", "props": {"id": "Willkommen-63c7074d", "bildSchluessel": "hero-startseite", "ueberschrift": "Nassauische Geschichte lebendig erleben", "text": "<p>Seit 2011 beschäftigen wir uns als Wiesbadener Verein mit der Geschichte des Nassauer Landes – vom Spätmittelalter bis zum Ersten Weltkrieg.</p><p>In unseren Darstellungen versuchen wir, diese Zeit möglichst authentisch erfahrbar zu machen und den Menschen von damals wieder ein Gesicht zu geben – auf Grundlage historischer Quellen und sorgfältiger Recherche.</p>", "knopf1": "Veranstaltungsanfrage stellen", "ziel1": "/fuer-veranstalter", "knopf2": "Unser Verein", "ziel2": "/verein", "hoehe": "mittel"}}, {"type": "Eckdaten", "props": {"id": "Eckdaten-2df9dfe3", "hintergrund": "gedaempft", "abstand": "eng", "eintraege": [{"symbol": "kalender", "text": "Seit", "hervorgehoben": "2011 aktiv"}, {"symbol": "leute", "text": "", "hervorgehoben": "3 Epochen dargestellt"}, {"symbol": "ort", "text": "Fokus", "hervorgehoben": "Region Wiesbaden"}]}}, {"type": "Zeitstrahl", "props": {"id": "Zeitstrahl-2a3a04ed", "ueberschrift": "Unsere Darstellungen", "hintergrund": "karte", "abstand": "weit", "punkte": [{"titel": "Spätmittelalter", "jahre": "1290–1310", "untertitel": "Grafschaft Nassau", "bildSchluessel": "epochenkarte-mittelalter", "ziel": "/epochen/mittelalter"}, {"titel": "Napoleonik", "jahre": "1815", "untertitel": "Herzogtum Nassau", "bildSchluessel": "epochenkarte-napoleonik", "ziel": "/epochen/1815"}, {"titel": "Erster Weltkrieg", "jahre": "1916/17", "untertitel": "Provinz Hessen-Nassau", "bildSchluessel": "epochenkarte-wk1", "ziel": "/epochen/wk1"}]}}, {"type": "Textabschnitt", "props": {"id": "Textabschnitt-ee61b973", "breite": "schmal", "abstand": "weit", "ausrichtung": "mitte", "textfarbe": "standard", "hintergrund": "keine", "inhalt": "<h2>Wer wir sind</h2><p>Diu lebendec Histôrje – mittelhochdeutsch für „die lebendige Geschichte“ – ist ein gemeinnütziger Verein aus Wiesbaden. Seit 2011 beschäftigen wir uns mit der Geschichte des Nassauer Landes vom Spätmittelalter bis zum Ersten Weltkrieg.</p><p>In unseren Darstellungen versuchen wir, diese Zeit möglichst authentisch erfahrbar zu machen – auf Grundlage historischer Quellen, archäologischer Funde und eigener Rekonstruktionen. Besonders interessiert uns dabei der Alltag gewöhnlicher Menschen und nicht nur das Leben von Herrschern oder Militärs.</p><p>Unsere Arbeit zeigen wir vor allem auf Veranstaltungen von Museen und historischen Einrichtungen, wo wir Geschichte durch Gespräche, Vorführungen und Displayarbeit für Besucher greifbar machen.</p>"}}, {"type": "Einzelbild", "props": {"id": "Einzelbild-70684008", "breite": "schmal", "abstand": "eng", "bildSchluessel": "gruppenfoto-startseite", "bildunterschrift": ""}}, {"type": "Knopf", "props": {"id": "Knopf-897859e7", "breite": "schmal", "abstand": "eng", "beschriftung": "Mehr über unseren Verein →", "ziel": "/verein", "zielFrei": "", "art": "schlicht", "ausrichtung": "mitte"}}, {"type": "Termine", "props": {"id": "Termine-443963b3", "breite": "breit", "abstand": "weit", "ueberschrift": "Nächste Veranstaltungen", "anzahl": 5}}, {"type": "Aktionskaesten", "props": {"id": "Aktionskaesten-3101ccf6", "hintergrund": "karte", "abstand": "weit", "kaesten": [{"titel": "Für Veranstalter", "text": "Sie planen eine Veranstaltung mit historischem Bildungsanspruch? Wir freuen uns über Ihre Anfrage.", "knopf": "Anfrage stellen", "ziel": "/fuer-veranstalter", "betont": true}, {"titel": "Für Interessierte", "text": "Geschichte begeistert Sie – und vielleicht möchten Sie mehr als nur zuschauen?", "knopf": "Mehr über uns erfahren", "ziel": "/verein", "betont": false}]}}], "root": {"props": {"title": "Startseite"}}}'::jsonb,
